using CoreBanking.Ledger.Application.Customers;
using CoreBanking.Ledger.Application.Tests.Postings;
using CoreBanking.Ledger.Domain;
using CoreBanking.Ledger.Domain.Accounts;

namespace CoreBanking.Ledger.Application.Tests.Customers;

public class CreateCustomerHandlerTests
{
    // Fictitious CPF, generated by the check digit algorithm.
    private const string FictitiousCpf = "390.533.447-05";

    private readonly PostingTestContext _ctx = new();

    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    private CreateCustomerHandler Handler() => new(_ctx.Customers, _ctx.Accounts, _ctx.UnitOfWork);

    [Fact]
    public async Task CreateCustomer_OpensDepositAccountWithSequentialCode()
    {
        var result = await Handler().HandleAsync(new CreateCustomerCommand("Maria Silva", FictitiousCpf), Ct);

        Assert.Equal("4.1.1.000001", result.AccountCode);
        var account = Assert.Single(_ctx.Accounts.Accounts, a => a.Id == result.AccountId);
        Assert.Equal(AccountType.CustomerDeposit, account.Type);
        Assert.Equal(result.CustomerId, account.CustomerId);
        Assert.Equal("Maria Silva", account.Name);
        Assert.Equal(1, _ctx.UnitOfWork.SaveChangesCalls);
    }

    [Fact]
    public async Task CreateCustomer_DuplicateDocument_Throws()
    {
        await Handler().HandleAsync(new CreateCustomerCommand("Maria Silva", FictitiousCpf), Ct);

        var ex = await Assert.ThrowsAsync<DomainException>(
            () => Handler().HandleAsync(new CreateCustomerCommand("Outra Pessoa", "39053344705"), Ct));

        Assert.Equal("customer.document_already_registered", ex.Code);
    }
}
